-- =====================================================================
--  Тестовые данные БД «Деканат» — МГТУ «СТАНКИН», Институт информационных технологий
--  ФАЙЛ СГЕНЕРИРОВАН СКРИПТОМ generate_seed.py — правьте скрипт, а не этот файл.
--  Все ФИО, документы, телефоны и адреса вымышленные.
--  Выполнять на пустой схеме после 01_schema.sql и 02_views_functions.sql.
-- =====================================================================
SET search_path TO deanery, public;
BEGIN;

-- Журнал изменений на время загрузки выключен: загрузка тестовых данных — не событие.
-- Остальные триггеры работают и проверяют все данные ниже.
DO $$
DECLARE t TEXT;
BEGIN
    FOR t IN SELECT DISTINCT event_object_table FROM information_schema.triggers
             WHERE trigger_schema = 'deanery' AND trigger_name = 'audit'
    LOOP
        EXECUTE format('ALTER TABLE deanery.%I DISABLE TRIGGER audit', t);
    END LOOP;
END $$;

