-- ================= Учебные поручения и расписание осеннего семестра 2026/27 =================
-- Учебные поручения: кто ведёт лекции, практики и лабораторные у каждой группы
-- Сетка занятий: день (1 — пн), пара, чётность недели. Потоковые лекции — одна строка на каждую группу потока. «Управление программными проектами» — лекции только до 25 октября

-- ---------- Посещаемость с 1 по 28 сентября 2026 ----------
-- Вероятность присутствия зависит от типа студента; выбор детерминирован (hashtext).
CREATE TEMP TABLE seed_attendance_rate (student_id INT PRIMARY KEY, rate NUMERIC) ON COMMIT DROP;
SELECT c.slot_id, s.student_id, c.lesson_date,
       h.v < r.rate * 1000,
       CASE WHEN h.v >= r.rate * 1000 THEN
            CASE WHEN h.v % 4 = 0 THEN 'Болезнь, есть справка'
                 WHEN h.v % 9 = 0 THEN 'Уважительная причина (соревнования, конференция)' END
       END
FROM v_schedule_calendar c
JOIN study_group g ON g.name = c.group_name
JOIN student     s ON s.group_id = g.group_id AND s.status_id = 1
JOIN seed_attendance_rate r ON r.student_id = s.student_id
CROSS JOIN LATERAL (SELECT abs(hashtext(c.slot_id || ':' || s.student_id || ':' || c.lesson_date)) % 1000 AS v) h
WHERE c.lesson_date <= DATE '2026-09-28';

