-- ---------- Заявки на исправление оценок в закрытых ведомостях ----------
-- Одобренная и применённая: преподаватель Новиков (novikov) ошибся при переносе баллов,
-- директор (smirnov) подтвердил. В оценке уже исправленное значение 43.
                              requested_by_id, requested_at, status, decided_by_id, decided_at, decision_comment)
SELECT g.grade_id, 34, FALSE, 43, FALSE,
       'Ошибка при переносе баллов из журнала: вместо 43 внесено 34 (служебная записка преподавателя)',
       5, gs.closed_date + TIME '10:00', 'applied', 1, gs.closed_date + 1 + TIME '09:30', 'Подтверждаю по журналу преподавателя'
FROM grade g JOIN grade_sheet gs ON gs.sheet_id = g.sheet_id
JOIN student s ON s.student_id = g.student_id
WHERE gs.examiner_id = 6 AND gs.status = 'closed' AND gs.sheet_kind = 'main' AND gs.stage = 'final'
  AND g.points = 43 AND s.status_id = 1
ORDER BY gs.closed_date DESC, g.grade_id LIMIT 1;

-- Ждёт решения: преподаватель Прохоров (prokhorov) просит добавить 3 балла
                              requested_by_id, requested_at)
SELECT g.grade_id, g.points, g.is_absent, g.points + 3, FALSE,
       'Не учтена защищённая в срок лабораторная работа № 4', 7, TIMESTAMPTZ '2026-09-27 15:20'
FROM grade g JOIN grade_sheet gs ON gs.sheet_id = g.sheet_id
JOIN student s ON s.student_id = g.student_id
WHERE gs.examiner_id = 24 AND gs.status = 'closed' AND gs.sheet_kind = 'main' AND gs.stage = 'final'
  AND g.points BETWEEN 40 AND 43 AND s.status_id = 1
ORDER BY gs.closed_date DESC, g.grade_id LIMIT 1;

DO $$
DECLARE t TEXT;
BEGIN
    FOR t IN SELECT DISTINCT event_object_table FROM information_schema.triggers
             WHERE trigger_schema = 'deanery' AND trigger_name = 'audit'
    LOOP
        EXECUTE format('ALTER TABLE deanery.%I ENABLE TRIGGER audit', t);
    END LOOP;
END $$;

COMMIT;
